// MarketplaceServiceHandler is an implementation of the ant.v1.MarketplaceService service.
type MarketplaceServiceHandler interface {
	PublishStrategy(context.Context, *connect.Request[v1.PublishStrategyRequest]) (*connect.Response[v1.PublishStrategyResponse], error)
	Subscribe(context.Context, *connect.Request[v1.SubscribeRequest]) (*connect.Response[v1.SubscribeResponse], error)
	Unsubscribe(context.Context, *connect.Request[v1.UnsubscribeRequest]) (*connect.Response[v1.UnsubscribeResponse], error)
	PurchaseStrategy(context.Context, *connect.Request[v1.PurchaseStrategyRequest]) (*connect.Response[v1.PurchaseStrategyResponse], error)
	ListPublished(context.Context, *connect.Request[v1.ListPublishedRequest]) (*connect.Response[v1.ListPublishedResponse], error)
	ListSubscriptions(context.Context, *connect.Request[v1.ListSubscriptionsRequest]) (*connect.Response[v1.ListSubscriptionsResponse], error)
	// Rating & comments
	RateStrategy(context.Context, *connect.Request[v1.RateStrategyRequest]) (*connect.Response[v1.RateStrategyResponse], error)
	ListRatings(context.Context, *connect.Request[v1.ListRatingsRequest]) (*connect.Response[v1.ListRatingsResponse], error)
	CommentOnStrategy(context.Context, *connect.Request[v1.CommentOnStrategyRequest]) (*connect.Response[v1.CommentOnStrategyResponse], error)
	ListComments(context.Context, *connect.Request[v1.ListCommentsRequest]) (*connect.Response[v1.ListCommentsResponse], error)
	// Admin
	SetStrategyPricing(context.Context, *connect.Request[v1.SetStrategyPricingRequest]) (*connect.Response[v1.SetStrategyPricingResponse], error)
	// Unpublish — author or admin can hide a strategy from the marketplace.
	UnpublishStrategy(context.Context, *connect.Request[v1.UnpublishMarketStrategyRequest]) (*connect.Response[v1.UnpublishMarketStrategyResponse], error)
	// Publisher dashboard stats.
	GetPublisherStats(context.Context, *connect.Request[v1.GetPublisherStatsRequest]) (*connect.Response[v1.GetPublisherStatsResponse], error)
	// Backtest — runs backtest for a marketplace-published strategy.
	// Strategy code is resolved server-side; client never sees it.
	// Returns a server stream of BacktestRunUpdate for real-time progress.
	RunMarketBacktest(context.Context, *connect.Request[v1.RunMarketBacktestRequest], *connect.ServerStream[v1.BacktestRunUpdate]) error
	// Live performance tracking
	GetLivePerformance(context.Context, *connect.Request[v1.GetLivePerformanceRequest]) (*connect.Response[v1.GetLivePerformanceResponse], error)
	LinkLiveAccount(context.Context, *connect.Request[v1.LinkLiveAccountRequest]) (*connect.Response[v1.LinkLiveAccountResponse], error)
	// Phase 2: AI strategy generation → compile → backtest → quality gate → auto-publish.
	// Streams progress events through all stages.
	GenerateAndPublish(context.Context, *connect.Request[v1.GenerateAndPublishRequest], *connect.ServerStream[v1.GenerateAndPublishEvent]) error
	// Phase 2: Generate from a parameter template.
	GenerateFromTemplate(context.Context, *connect.Request[v1.GenerateFromTemplateRequest], *connect.ServerStream[v1.GenerateAndPublishEvent]) error
	// Phase 2: List available strategy parameter templates.
	ListStrategyTemplates(context.Context, *connect.Request[v1.ListStrategyTemplatesRequest]) (*connect.Response[v1.ListStrategyTemplatesResponse], error)
	// Phase 2 Admin: List auto-generation tasks.
	ListAutoGenTasks(context.Context, *connect.Request[v1.ListAutoGenTasksRequest]) (*connect.Response[v1.ListAutoGenTasksResponse], error)
	// Phase 2 Admin: Approve an auto-generated task → publish to marketplace.
	ApproveAutoGenTask(context.Context, *connect.Request[v1.ApproveAutoGenTaskRequest]) (*connect.Response[v1.ApproveAutoGenTaskResponse], error)
	// Phase 2 Admin: Reject an auto-generated task.
	RejectAutoGenTask(context.Context, *connect.Request[v1.RejectAutoGenTaskRequest]) (*connect.Response[v1.RejectAutoGenTaskResponse], error)
	// Phase 2 Admin: Trigger batch generation (enqueue tasks).
	TriggerBatchGeneration(context.Context, *connect.Request[v1.TriggerBatchGenerationRequest]) (*connect.Response[v1.TriggerBatchGenerationResponse], error)
	// Phase 3.1: Strategy leaderboard.
	ListLeaderboard(context.Context, *connect.Request[v1.ListLeaderboardRequest]) (*connect.Response[v1.ListLeaderboardResponse], error)
	// Phase 3.2: Start free trial for a strategy.
	StartTrial(context.Context, *connect.Request[v1.StartTrialRequest]) (*connect.Response[v1.StartTrialResponse], error)
	// Phase 3.3: Compare strategies side by side.
	CompareStrategies(context.Context, *connect.Request[v1.CompareStrategiesRequest]) (*connect.Response[v1.CompareStrategiesResponse], error)
	// Phase 3.5: Get public strategy info for share landing page (no auth required).
	GetStrategyPublicInfo(context.Context, *connect.Request[v1.GetStrategyPublicInfoRequest]) (*connect.Response[v1.GetStrategyPublicInfoResponse], error)
	// Phase 1.3: Provider identity verification.
	RequestVerification(context.Context, *connect.Request[v1.RequestVerificationRequest]) (*connect.Response[v1.RequestVerificationResponse], error)
	AdminProcessVerification(context.Context, *connect.Request[v1.AdminProcessVerificationRequest]) (*connect.Response[v1.AdminProcessVerificationResponse], error)
	// Phase 4.1: Admin strategy management.
	AdminListStrategies(context.Context, *connect.Request[v1.AdminListStrategiesRequest]) (*connect.Response[v1.AdminListStrategiesResponse], error)
	AdminFeatureStrategy(context.Context, *connect.Request[v1.AdminFeatureStrategyRequest]) (*connect.Response[v1.AdminFeatureStrategyResponse], error)
	// Phase 4.2: Refund request workflow.
	RequestRefund(context.Context, *connect.Request[v1.RequestRefundRequest]) (*connect.Response[v1.RequestRefundResponse], error)
	AdminListRefundRequests(context.Context, *connect.Request[v1.AdminListRefundRequestsRequest]) (*connect.Response[v1.AdminListRefundRequestsResponse], error)
	AdminProcessRefund(context.Context, *connect.Request[v1.AdminProcessRefundRequest]) (*connect.Response[v1.AdminProcessRefundResponse], error)
	// Phase 4.3: Marketplace analytics dashboard.
	GetMarketplaceAnalytics(context.Context, *connect.Request[v1.GetMarketplaceAnalyticsRequest]) (*connect.Response[v1.MarketplaceAnalytics], error)
	GetTopStrategies(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[v1.TopStrategiesResponse], error)
	GetTopProviders(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[v1.TopProvidersResponse], error)
	// Phase 4.5: Coupon / discount codes.
	ValidateCoupon(context.Context, *connect.Request[v1.ValidateCouponRequest]) (*connect.Response[v1.ValidateCouponResponse], error)
	CreateCoupon(context.Context, *connect.Request[v1.CreateCouponRequest]) (*connect.Response[v1.CreateCouponResponse], error)
	ListCoupons(context.Context, *connect.Request[v1.ListCouponsRequest]) (*connect.Response[v1.ListCouponsResponse], error)
	DisableCoupon(context.Context, *connect.Request[v1.DisableCouponRequest]) (*connect.Response[v1.DisableCouponResponse], error)
	// Phase 4.6: Provider earnings & withdrawal.
	GetProviderEarnings(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[v1.ProviderEarnings], error)
	ListProviderTransactions(context.Context, *connect.Request[v1.ListProviderTransactionsRequest]) (*connect.Response[v1.ListProviderTransactionsResponse], error)
	// Phase 5.1: AI strategy iteration — decay detection + optimization.
	DetectStrategyDecay(context.Context, *connect.Request[v1.DetectStrategyDecayRequest]) (*connect.Response[v1.DetectStrategyDecayResponse], error)
	ListOptimizationTasks(context.Context, *connect.Request[v1.ListOptimizationTasksRequest]) (*connect.Response[v1.ListOptimizationTasksResponse], error)
	GetOptimizationTask(context.Context, *connect.Request[v1.GetOptimizationTaskRequest]) (*connect.Response[v1.GetOptimizationTaskResponse], error)
	RejectOptimizationTask(context.Context, *connect.Request[v1.RejectOptimizationTaskRequest]) (*connect.Response[v1.RejectOptimizationTaskResponse], error)
	PublishOptimization(context.Context, *connect.Request[v1.PublishOptimizationRequest]) (*connect.Response[v1.PublishOptimizationResponse], error)
	PreviewOptimization(context.Context, *connect.Request[v1.PreviewOptimizationRequest]) (*connect.Response[v1.PreviewOptimizationResponse], error)
	// Phase 5.2: Strategy bundles.
	CreateBundle(context.Context, *connect.Request[v1.CreateBundleRequest]) (*connect.Response[v1.CreateBundleResponse], error)
	ListBundles(context.Context, *connect.Request[v1.ListBundlesRequest]) (*connect.Response[v1.ListBundlesResponse], error)
	GetBundle(context.Context, *connect.Request[v1.GetBundleRequest]) (*connect.Response[v1.GetBundleResponse], error)
	PurchaseBundle(context.Context, *connect.Request[v1.PurchaseBundleRequest]) (*connect.Response[v1.PurchaseBundleResponse], error)
	DeleteBundle(context.Context, *connect.Request[v1.DeleteBundleRequest]) (*connect.Response[v1.DeleteBundleResponse], error)
	// Phase 5.3: Tiered fee rates.
	ListFeeTiers(context.Context, *connect.Request[emptypb.Empty]) (*connect.Response[v1.ListFeeTiersResponse], error)
	UpdateFeeTier(context.Context, *connect.Request[v1.UpdateFeeTierRequest]) (*connect.Response[v1.UpdateFeeTierResponse], error)
	GetProviderFeeTier(context.Context, *connect.Request[v1.GetProviderFeeTierRequest]) (*connect.Response[v1.GetProviderFeeTierResponse], error)
}

